// Package migrations embeds Tether's goose migrations, one set per dialect (port plan sections 3 and
// 13.1), in the layout the database module expects: sqlite/NNNNN_name.sql and postgres/NNNNN_name.sql,
// with the same versions in both (internal/migrate checks parity).
//
// 00001_schema.sql is the squashed schema of the old store at its migration 0101. The SQLite file is
// generated by internal/migrate's schema test from the old migrations and proven equal to them there; the
// Postgres file is hand-maintained and proven equivalent to the SQLite one by the same package. No
// per-version ladders from the old tree belong here.
package migrations

import (
	"embed"
	"io/fs"
)

//go:embed sqlite/*.sql postgres/*.sql
var fsys embed.FS

// FS returns the migration tree and its root directory (<root>/<dialect>/NNNNN_name.sql).
func FS() (fs.FS, string) { return fsys, "." }
